import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.regex.*;
import org.apache.commons.text.StringEscapeUtils;

public class ReportExportServlet extends HttpServlet {

    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    // Allow alphanumeric, spaces, and common punctuation for report names
    private static final Pattern SAFE_NAME = Pattern.compile("^[a-zA-Z0-9 _\\-]{1,64}$");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String sessionToken = req.getHeader("X-Session-Token");
        if (sessionToken == null || !validateSession(sessionToken)) {
            resp.sendError(401, "Unauthorized");
            return;
        }

        String reportId = req.getParameter("id");
        String format = req.getParameter("format");
        String customFilter = req.getParameter("filter");

        if (reportId == null || !reportId.matches("\\d{1,10}")) {
            resp.sendError(400, "Invalid report ID");
            return;
        }

        // Format validation - only allow known formats
        if (format != null && !format.matches("(csv|json|xml)")) {
            resp.sendError(400, "Invalid format");
            return;
        }

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {
            // First get report metadata safely
            PreparedStatement metaStmt = conn.prepareStatement(
                "SELECT report_name, owner_id, query_template FROM reports WHERE id = ?");
            metaStmt.setInt(1, Integer.parseInt(reportId));
            ResultSet metaRs = metaStmt.executeQuery();

            if (!metaRs.next()) {
                resp.sendError(404, "Report not found");
                return;
            }

            String reportName = metaRs.getString("report_name");
            String queryTemplate = metaRs.getString("query_template");
            int ownerId = metaRs.getInt("owner_id");

            // Build the data query - template comes from DB, filter from user
            String dataQuery;
            if (customFilter != null && !customFilter.isEmpty()) {
                // The query_template contains something like:
                // "SELECT * FROM sales_data WHERE region = 'EAST'"
                // We append the user's filter condition
                dataQuery = queryTemplate + " AND " + customFilter;
            } else {
                dataQuery = queryTemplate;
            }

            Statement dataStmt = conn.createStatement();
            ResultSet dataRs = dataStmt.executeQuery(dataQuery);

            // Stream results
            resp.setContentType(getContentType(format));
            resp.setHeader("Content-Disposition", 
                "attachment; filename=\"" + sanitizeFilename(reportName) + "." + format + "\"");

            PrintWriter out = resp.getWriter();
            ResultSetMetaData rsmd = dataRs.getMetaData();
            int colCount = rsmd.getColumnCount();

            if ("csv".equals(format)) {
                for (int i = 1; i <= colCount; i++) {
                    out.print(rsmd.getColumnName(i));
                    if (i < colCount) out.print(",");
                }
                out.println();
                while (dataRs.next()) {
                    for (int i = 1; i <= colCount; i++) {
                        String val = dataRs.getString(i);
                        out.print(StringEscapeUtils.escapeCsv(val != null ? val : ""));
                        if (i < colCount) out.print(",");
                    }
                    out.println();
                }
            } else {
                // JSON output
                out.println("[");
                boolean first = true;
                while (dataRs.next()) {
                    if (!first) out.println(",");
                    out.print("{");
                    for (int i = 1; i <= colCount; i++) {
                        String val = dataRs.getString(i);
                        out.print("\"" + rsmd.getColumnName(i) + "\":");
                        out.print("\"" + StringEscapeUtils.escapeJson(val != null ? val : "") + "\"");
                        if (i < colCount) out.print(",");
                    }
                    out.print("}");
                    first = false;
                }
                out.println("]");
            }

        } catch (SQLException e) {
            resp.sendError(500, "Database error");
        }
    }

    private boolean validateSession(String token) {
        // Validates against session store
        return token != null && token.length() == 64;
    }

    private String sanitizeFilename(String name) {
        return name.replaceAll("[^a-zA-Z0-9_\\- ]", "_");
    }

    private String getContentType(String format) {
        if ("csv".equals(format)) return "text/csv";
        if ("xml".equals(format)) return "application/xml";
        return "application/json";
    }
}
